'use client';
import { STRIPE_SECRET } from '@/lib/payments'; // kéo secret vào client graph

export function CheckoutButton({ cartId }: { cartId: string }) {
  async function handlePay() {
    // ❌ Gọi thẳng Stripe từ trình duyệt VỚI SECRET KEY
    await fetch('https://api.stripe.com/v1/payment_intents', {
      method: 'POST',
      headers: { Authorization: `Bearer ${STRIPE_SECRET}` },
      body: new URLSearchParams({ cartId, currency: 'vnd' }),
    });
  }
  return <button onClick={handlePay}>Thanh toán</button>;
}

