  apiVersion: '2024-06-20',
});

// 2) Client gọi Route Handler của ta — KHÔNG gọi Stripe trực tiếp
// app/api/checkout/route.ts
export async function POST(req: Request) {
  const session = await auth(); // xác thực TRƯỚC, tính tiền SAU
  if (!session) return Response.json({ error: 'Unauthorized' }, { status: 401 });

  const { cartId } = await req.json();
  const amount = await priceCart(cartId); // ✅ amount tính server-side — tin client là mất tiền
  const intent = await stripe.paymentIntents.create({ amount, currency: 'vnd' });
  return Response.json({ clientSecret: intent.client_secret }); // chỉ lộ clientSecret an toàn
}

